/**
 * Typed replacement for `Action` JSON strings.
 * Platform receives these from `handle_event()` and executes each one.
 */
sealed class CfeAction {
    
    data class DecryptMessage(
        val `contactId`: kotlin.String, 
        val `ciphertext`: kotlin.ByteArray) : CfeAction()
        
    {
        

        companion object
    }
    
    data class EncryptMessage(
        val `contactId`: kotlin.String, 
        val `plaintext`: kotlin.ByteArray) : CfeAction()
        
    {
        

        companion object
    }
    
    data class ArchiveSession(
        val `contactId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    data class MessageDecrypted(
        val `contactId`: kotlin.String, 
        val `messageId`: kotlin.String, 
        val `plaintext`: kotlin.ByteArray) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * Open a new session with `contact_id` — a device — as INITIATOR over the one held: fetch
     * that device's bundle and answer with `SessionBundleFetched` (or `SessionBundleUnavailable`).
     * Do not call `reopen_session` for it: the event's answer carries the save and the drained
     * queue that the call cannot. Nothing is sent — the handshake header rides on the next
     * message. Raised by the PQXDH v2 upgrade sweep.
     */
    data class OpenSession(
        val `contactId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * Message queued inside the core behind an in-flight session init. Nothing lost.
     */
    data class MessageQueuedPendingInit(
        val `contactId`: kotlin.String, 
        val `queuedCount`: kotlin.UInt) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * Write `data` into `slot`; empty `data` is a delete sentinel where the slot says so.
     */
    data class SaveToSecureStore(
        val `slot`: CfeSecureStoreSlot, 
        val `data`: kotlin.ByteArray) : CfeAction()
        
    {
        

        companion object
    }
    
    data class PersistAck(
        val `messageId`: kotlin.String, 
        val `timestamp`: kotlin.ULong) : CfeAction()
        
    {
        

        companion object
    }
    
    data class PruneAckStore(
        val `cutoffTs`: kotlin.ULong) : CfeAction()
        
    {
        

        companion object
    }
    
    data class MarkMessageDelivered(
        val `messageId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * A message already handled (ACK cache, platform DB, or its ratchet key already used).
     * Terminal: record it as processed and advance the stream cursor past it.
     */
    data class DuplicateDropped(
        val `messageId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * A message whose payload does not parse (garbage, or a retired suite): it can never open.
     * Terminal: record it as processed and advance the stream cursor past it. Nothing is sent.
     */
    data class MalformedDropped(
        val `messageId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    data class OpenReceiving(
        val `contactId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    data class SendEncryptedMessage(
        val `to`: kotlin.String, 
        val `payload`: kotlin.ByteArray, 
        val `messageId`: kotlin.String, 
        val `contentType`: kotlin.UByte) : CfeAction()
        
    {
        

        companion object
    }
    
    data class SendReceipt(
        val `messageId`: kotlin.String, 
        val `status`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * We could not read `message_id` from `contact_id`: send `payload` to that device as a
     * DECRYPTION_ERROR (content type 28) envelope, sealed-sender, and acknowledge the message.
     * The core built and sealed `payload`; one per unread message.
     * `enveloped`: `payload` is a session envelope — send it as the sealed inner's envelope with
     * no certificate; otherwise it is the X25519 box, sent as before.
     */
    data class SendDecryptionError(
        val `contactId`: kotlin.String, 
        val `messageId`: kotlin.String, 
        val `payload`: kotlin.ByteArray, 
        val `enveloped`: kotlin.Boolean) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * The peer could not read our current state with `contact_id`; it is retired and the next
     * send opens a new one — without a one-time prekey when `without_one_time_prekey`.
     */
    data class SessionRetired(
        val `contactId`: kotlin.String, 
        val `withoutOneTimePrekey`: kotlin.Boolean) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * The peer could not read `message_id`: send it again to `contact_id` as a new message.
     */
    data class ResendMessage(
        val `contactId`: kotlin.String, 
        val `messageId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    data class NotifyNewMessage(
        val `chatId`: kotlin.String, 
        val `preview`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    data class NotifySessionCreated(
        val `contactId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    data class NotifyError(
        val `code`: kotlin.String, 
        val `message`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    data class ScheduleTimer(
        val `timerId`: kotlin.String, 
        val `delayMs`: kotlin.ULong) : CfeAction()
        
    {
        

        companion object
    }
    
    data class CancelTimer(
        val `timerId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    data class CallSignalDecrypted(
        val `contactId`: kotlin.String, 
        val `messageId`: kotlin.String, 
        val `protoBytes`: kotlin.ByteArray) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * A silent control frame other than a call signal (13, 14, 25, 26, 27, 29), named by byte 5
     * of its KNST frame; `body` is without the header. Never a chat message: handle by
     * `content_type` and record the message processed.
     */
    data class ControlFrameDecrypted(
        val `contactId`: kotlin.String, 
        val `messageId`: kotlin.String, 
        val `contentType`: kotlin.UByte, 
        val `body`: kotlin.ByteArray) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * Platform must query its persistent ACK store for `message_id` and reply with `AckDbResult`.
     */
    data class CheckAckInDb(
        val `messageId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCfeAction : FfiConverterRustBuffer<CfeAction>{
    override fun read(buf: ByteBuffer): CfeAction {
        return when(buf.getInt()) {
            1 -> CfeAction.DecryptMessage(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                )
            2 -> CfeAction.EncryptMessage(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                )
            3 -> CfeAction.ArchiveSession(
                FfiConverterString.read(buf),
                )
            4 -> CfeAction.MessageDecrypted(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                )
            5 -> CfeAction.OpenSession(
                FfiConverterString.read(buf),
                )
            6 -> CfeAction.MessageQueuedPendingInit(
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            7 -> CfeAction.SaveToSecureStore(
                FfiConverterTypeCfeSecureStoreSlot.read(buf),
                FfiConverterByteArray.read(buf),
                )
            8 -> CfeAction.PersistAck(
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                )
            9 -> CfeAction.PruneAckStore(
                FfiConverterULong.read(buf),
                )
            10 -> CfeAction.MarkMessageDelivered(
                FfiConverterString.read(buf),
                )
            11 -> CfeAction.DuplicateDropped(
                FfiConverterString.read(buf),
                )
            12 -> CfeAction.MalformedDropped(
                FfiConverterString.read(buf),
                )
            13 -> CfeAction.OpenReceiving(
                FfiConverterString.read(buf),
                )
            14 -> CfeAction.SendEncryptedMessage(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUByte.read(buf),
                )
            15 -> CfeAction.SendReceipt(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            16 -> CfeAction.SendDecryptionError(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterBoolean.read(buf),
                )
            17 -> CfeAction.SessionRetired(
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            18 -> CfeAction.ResendMessage(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            19 -> CfeAction.NotifyNewMessage(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            20 -> CfeAction.NotifySessionCreated(
                FfiConverterString.read(buf),
                )
            21 -> CfeAction.NotifyError(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            22 -> CfeAction.ScheduleTimer(
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                )
            23 -> CfeAction.CancelTimer(
                FfiConverterString.read(buf),
                )
            24 -> CfeAction.CallSignalDecrypted(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                )
            25 -> CfeAction.ControlFrameDecrypted(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUByte.read(buf),
                FfiConverterByteArray.read(buf),
                )
            26 -> CfeAction.CheckAckInDb(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CfeAction) = when(value) {
        is CfeAction.DecryptMessage -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`contactId`)
                + FfiConverterByteArray.allocationSize(value.`ciphertext`)
            )
        }
        is CfeAction.EncryptMessage -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`contactId`)
                + FfiConverterByteArray.allocationSize(value.`plaintext`)
            )
        }
        is CfeAction.ArchiveSession -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`contactId`)
            )
        }
        is CfeAction.MessageDecrypted -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`contactId`)
