/**
 * Typed replacement for `IncomingEvent` JSON strings.
 * Platform creates one of these variants and passes to `handle_event()`.
 */
sealed class CfeIncomingEvent {
    
    /**
     * `envelope_session`: the session whose envelope the message came in (`open_envelope`),
     * set instead of `sender_certificate`.
     */
    data class MessageReceived(
        val `messageId`: kotlin.String, 
        val `from`: kotlin.String, 
        val `data`: kotlin.ByteArray, 
        val `contentType`: kotlin.UByte, 
        val `senderCertificate`: SenderCertificate?, 
        val `envelopeSession`: kotlin.String?) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    data class OutgoingMessage(
        val `contactId`: kotlin.String, 
        val `messageId`: kotlin.String, 
        val `plaintext`: kotlin.ByteArray, 
        val `contentType`: kotlin.UByte) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    data class OutgoingCallSignal(
        val `contactId`: kotlin.String, 
        val `messageId`: kotlin.String, 
        val `protoBytes`: kotlin.ByteArray) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    data class SessionInitCompleted(
        val `contactId`: kotlin.String, 
        val `sessionData`: kotlin.ByteArray) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    data class AckReceived(
        val `messageId`: kotlin.String) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    /**
     * The answer to `CfeAction::OpenSession`: the bundle of that one device. The core reopens
     * from it and answers with the save, the messages that waited, or `OPEN_SESSION_REFUSED`.
     */
    data class SessionBundleFetched(
        val `contactId`: kotlin.String, 
        val `bundle`: BinaryKeyBundle) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    /**
     * The answer to `CfeAction::OpenSession` when no bundle could be fetched. The held session
     * stays; the core stops waiting for the open now instead of at its time-out.
     */
    data class SessionBundleUnavailable(
        val `contactId`: kotlin.String) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    object NetworkReconnected : CfeIncomingEvent()
    
    
    object AppLaunched : CfeIncomingEvent()
    
    
    data class TimerFired(
        val `timerId`: kotlin.String) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    /**
     * Platform ACK DB lookup result — response to `CheckAckInDb` action.
     */
    data class AckDbResult(
        val `messageId`: kotlin.String, 
        val `isProcessed`: kotlin.Boolean) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    /**
     * A heartbeat message was received from the peer.
     */
    data class HeartbeatReceived(
        val `contactId`: kotlin.String, 
        val `messageId`: kotlin.String, 
        val `data`: kotlin.ByteArray) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    /**
     * A DECRYPTION_ERROR (content type 28) arrived from `contact_id` — the device its sender
     * certificate names; `payload` is the envelope's sealed box. Answered with `SessionRetired` +
     * `ResendMessage`, `ResendMessage` alone, or nothing when the error is stale.
     * `opened`: `payload` came out of a session envelope and is the error itself.
     */
    data class DecryptionErrorReceived(
        val `contactId`: kotlin.String, 
        val `payload`: kotlin.ByteArray, 
        val `opened`: kotlin.Boolean) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    

    
    companion object
}

